package gg.pixelkingdomwars.nativeclient.renderer

import com.badlogic.gdx.utils.JsonReader
import com.badlogic.gdx.utils.JsonValue
import com.badlogic.gdx.utils.JsonWriter
import java.io.File
import kotlin.test.*
import org.junit.Test

/** Samples are generated by executing canonical TroopFx and BattleScene methods, with the
 * installed Phaser easing. They isolate body transforms; authored external FX have separate tests. */
class HeroBodyTravelTest {
    private val reader=JsonReader()
    private val reference=reader.parse(checkNotNull(javaClass.getResourceAsStream("/hero/travel-source-reference.json"))
        .bufferedReader().use { it.readText() })
    private val root=System.getenv("PKW_COMBAT_PACK")?.let(::File) ?: File("../app/src/main/assets/native")
    private val render=reader.parse(root.resolve("render-catalog.json").readText())
    private val catalogue=reader.parse(root.resolve("catalogue.json").readText())
    private val library=CombatArt.catalogue(render)
    private val frames=render.get("actors").filter { it.getInt("level",1)==1 }.associate { it.getString("type") to it.getString("frameKey") }
    private fun plan(case:JsonValue,events:List<PresentationEvent> = case.get("events").map { PresentationEvent.fromJson(it.toJson(JsonWriter.OutputType.json)) }):CombatVisualPlan {
        val boundary=case.getFloat("fromTick")
        val pixel=catalogue.get("presentation").getFloat("tilePixels")
        val cadence=reference.getInt("positionCadenceTicks")
        // Source capture uses identity ux/uy, so this transform-only fixture has a 1:1 input-pixel scale.
        val scene=BattleScene(BaseScene(emptyList(),32,32,pixel),
            PresentationRevision(case.getString("name"),"source-reference",reference.getInt("simVersion"),0,0,events),
            frames,pixel,reference.getFloat("tickMs"),cadence,cadence,
            presentationStart=if(boundary>0)BattlePresentationStart.ColdPrefix(boundary) else BattlePresentationStart.Continuous)
        return CombatVisualPlan(scene,BattleVisualModel(events,cadence),library)
    }
    private fun verify(predicate:(String)->Boolean) {
        val cases=reference.get("cases").filter { predicate(it.getString("name")) }
        assertTrue(cases.isNotEmpty())
        for(case in cases) {
            val p=plan(case)
            for(sample in case.get("samples")) {
                val tick=sample.getFloat("tick");val label="${case.getString("name")} tick=$tick"
                val actual=p.actor(1,tick)
                if(actual==null) { assertFalse(sample.getBoolean("alive"),label);continue }
                assertEquals(sample.getFloat("x"),actual.x,.002f,"$label x")
                assertEquals(sample.getFloat("y"),actual.y,.002f,"$label y")
                assertEquals(sample.getFloat("depth"),actual.depth,.002f,"$label depth follows visible feet")
                if(!sample.getBoolean("alive"))assertEquals("defeat",actual.clip.key.removePrefix("hero_vex_").removePrefix("hero_theo_"),label)
            }
            assertTrue(p.missingCoverage.isEmpty(),"${case.getString("name")}: ${p.missingCoverage}")
        }
    }
    @Test fun `both travel families ease from the visible position and latest queued position resumes after unlock`() = verify { it.endsWith("-queued") }
    @Test fun `replacement starts at current eased position and old unlock cannot resume queued movement`() = verify { it.endsWith("-replace") }
    @Test fun `a new non-travel body lock preserves the in-flight transform and owns the pending position`() = verify { it.endsWith("-nonTravel") }
    @Test fun `death freezes the visible travel point and same-tick death takes precedence`() = verify { it.endsWith("-death") || it.endsWith("-sameTickDeath") }
    @Test fun `cold prefix restores only active travel from snapped history for the remaining source lock`() = verify { "-cold-" in it }
    @Test fun `completed and zero-distance travel retain their destination without a model-position snapback`() = verify { it.endsWith("-retainedTarget") || it.endsWith("-zeroTravel") }
    @Test fun `higher body priority does not suppress travel but its original unlock still owns queued position`() = verify { it.endsWith("-priorityGuard") }
    @Test fun `cold body restoration preserves elapsed eat bloat and fake death phases`() {
        verify { "-cold-body-" in it }
        for(case in reference.get("cases").filter { it.getBoolean("bodyCase",false) }) {
            val p=plan(case);val expected=case.get("boundaryBody").map { it.asString() }
            val sprite=assertNotNull(p.actor(1,case.getFloat("fromTick")))
            assertEquals(expected.first(),sprite.frameKey,"${case.getString("name")} must restore the source-selected phase")
            if(case.getString("name").endsWith("fakeDeath")) {
                assertEquals(1,expected.size)
                assertEquals(expected.single(),assertNotNull(p.actor(1,case.getFloat("fromTick")+.25f)).frameKey,
                    "Elapsed fake death holds the final play-dead frame")
            }
        }
    }
    @Test fun `cold source order hydrates later positions before restoring newer attack and older skill`() {
        val case=reference.get("cases").first { it.getString("name")=="theodor-cold-body-bloat" }
        val events=case.get("events").map { PresentationEvent.fromJson(it.toJson(JsonWriter.OutputType.json)) }
        val indexed=case.get("events").mapIndexed { i,e->i to e }
        val tickMs=reference.getFloat("tickMs");val boundary=case.getFloat("fromTick")
        val art=library.getValue(frames.getValue("theodor"))
        val motion=HeroBodyMotion(indexed,PositionDelivery.compile(events,reference.getInt("positionCadenceTicks"),
            reference.getInt("positionCadenceTicks"),tickMs,boundary),art,tickMs,1f,BattlePresentationStart.ColdPrefix(boundary))
        for((order,event) in indexed.filter { it.second.getString("e") in setOf("heroAttack","heroSkill") && it.second.getInt("t")>=10 }) {
            val visible=assertNotNull(motion.sample(boundary*tickMs,order),event.toString())
            assertEquals(123f,visible.x);assertEquals(87f,visible.y)
        }
    }
    @Test fun `reverse seeking and prediction replacement retain no future body travel`() {
        for(case in reference.get("cases").filter { it.getString("name").endsWith("-queued") }) {
            val p=plan(case);val ticks=case.get("samples").map { it.getFloat("tick") }
            val initial=ticks.associateWith { p.actor(1,it) }
            for(tick in ticks.reversed())assertEquals(initial[tick],p.actor(1,tick))
            val kept=case.get("events").filter { it.getString("e")!="heroSkill" }.map { PresentationEvent.fromJson(it.toJson(JsonWriter.OutputType.json)) }
            val replacement=plan(case,kept)
            assertNotEquals(p.actor(1,4f)?.x,replacement.actor(1,4f)?.x,"Removed prediction must not retain a travelling origin or destination")
        }
    }
    @Test fun `crimson external trail retains its independent linear event-origin trajectory`() {
        val case=reference.get("cases").first { it.getString("name")=="vex-queued" }
        val p=plan(case);val output=mutableListOf<CombatSprite>()
        p.transientSprites(4f,output)
        val trail=output.single { it.clip.key=="fx_vex_dashtrail" }
        val event=case.get("events").first { it.getString("e")=="heroSkill" }
        val art=library.getValue(frames.getValue("vex"))
        val ratio=1f/art.heroBodyDefaultTicks.getValue("default")
        assertEquals(event.getFloat("fromX")+(event.getFloat("toX")-event.getFloat("fromX"))*ratio,trail.x,.001f)
        assertNotEquals(trail.x,p.actor(1,4f)?.x,"Body starts at visible sprite; authored external FX still starts at event.from")
    }
}
